import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"检索文献","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/search.md","filePath":"zh/guide/search.md","lastUpdated":1792570296000}'),d={name:"zh/guide/search.md"};function n(s,t,h,i,l,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="检索文献" tabindex="-1">检索文献 <a class="header-anchor" href="#检索文献" aria-label="Permalink to &quot;检索文献&quot;">​</a></h1><p>描述你希望理解的问题，PaperSeek 会生成适合数据源的检索式，并展示检索如何逐步展开。</p><h2 id="工作区入口" tabindex="-1">工作区入口 <a class="header-anchor" href="#工作区入口" aria-label="Permalink to &quot;工作区入口&quot;">​</a></h2><p>检索设置、运行过程、检索结果是模块内的三个子页。模型默认值位于侧栏底部的独立设置页；来源、领域与检索预算留在检索草稿中。运行时可在页首停止任务，切换子页不会重跑任务。</p><h2 id="写清研究问题" tabindex="-1">写清研究问题 <a class="header-anchor" href="#写清研究问题" aria-label="Permalink to &quot;写清研究问题&quot;">​</a></h2><p>说明研究对象和关注的关系，必要时加入方法、群体、时期或场景。</p><p><strong>宽泛：</strong>“开源软件。”<br><strong>具体：</strong>“不同资金支持机制如何影响开源软件的长期维护？”</p><p>支持中英文自然语言，不必手写布尔检索式。问题最多 10,000 个字符。</p><h2 id="选择数据源和范围" tabindex="-1">选择数据源和范围 <a class="header-anchor" href="#选择数据源和范围" aria-label="Permalink to &quot;选择数据源和范围&quot;">​</a></h2><p>一次任务从<strong>一个选定数据源</strong>开始。多路召回不代表同一任务会同时查询八个来源。</p><p>OpenAlex、arXiv 和 WoS 有源特定的领域筛选；其他来源使用领域提示辅助规划检索式。文本提示不等于数据库层面的强制过滤。</p><p>OpenAlex 引用扩展在预算内增加参考文献和施引文献，也会增加请求和耗时。</p><h2 id="选择预算" tabindex="-1">选择预算 <a class="header-anchor" href="#选择预算" aria-label="Permalink to &quot;选择预算&quot;">​</a></h2><table tabindex="0"><thead><tr><th>界面选项</th><th>API / CLI 值</th><th>用途</th></tr></thead><tbody><tr><td>Auto</td><td>—</td><td>由 PaperSeek 选择检索预算</td></tr><tr><td>快速</td><td><code>fast</code></td><td>较小召回与评分预算</td></tr><tr><td>均衡</td><td><code>medium</code></td><td>扩大覆盖与排序深度</td></tr><tr><td>深入</td><td><code>high</code></td><td>更多候选与引用探索</td></tr><tr><td>最大</td><td><code>max</code></td><td>最大的有界检索预算</td></tr></tbody></table><p>预算限制工作量，不保证固定文献数或完成时间。更大预算可能更慢、更贵，收窄问题可能比选择最大档更有帮助。</p><h2 id="理解四个阶段" tabindex="-1">理解四个阶段 <a class="header-anchor" href="#理解四个阶段" aria-label="Permalink to &quot;理解四个阶段&quot;">​</a></h2><ol><li><strong>检索意图与检索式</strong>：理解范围，制定策略。</li><li><strong>检索迭代</strong>：根据数据源反馈测试与调整查询。</li><li><strong>候选召回与排序</strong>：收集候选、按需扩展引用、初排序，再评估相关性。模型先按每批 64 篇给候选打分，再按每组 32 篇为得分较高的论文写“排序理由”；最多同时进行 8 批或 8 组，打分和写理由各有一行进度。</li><li><strong>文献结果</strong>：整理阅读清单与导出。</li></ol><p>页面展示阶段状态和详情，不再显示原始终端日志框。</p><h3 id="区分几种数量" tabindex="-1">区分几种数量 <a class="header-anchor" href="#区分几种数量" aria-label="Permalink to &quot;区分几种数量&quot;">​</a></h3><p>数据源报告数万条命中时，程序可能只下载了一页。<strong>数据源命中</strong>、<strong>已召回候选</strong>和<strong>最终结果</strong>不是同一个集合。</p><p>过宽的查询可能先收窄再获取候选池。重复或无进展的改写会停止，并可回选历史中更合适的查询，而非无条件采用最后一轮。候选池始终受预算限制，输出不代表穷尽相关文献。</p><h2 id="停止与重连" tabindex="-1">停止与重连 <a class="header-anchor" href="#停止与重连" aria-label="Permalink to &quot;停止与重连&quot;">​</a></h2><p>点击<strong>停止</strong>请求取消，正在进行的工作收尾时可能短暂显示<strong>正在取消</strong>。</p><p>刷新持久化任务会恢复已保存的状态，网络重连不是新检索。重试已结束或取消的任务会开始新的执行，不会重开旧执行。</p><p>在线排队见<a href="./../online/#任务排队">在线版概览</a>，匿名会话见<a href="./../online/privacy#不登录检索">数据与隐私</a>。</p>',25)])])}const u=a(d,[["render",n]]);export{g as __pageData,u as default};
